import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";import{Sn as i,_n as a,bn as o,gn as s,hn as c,vn as l,xn as u,yn as d}from"./chunks/assets.CH6La9WX.js";var f=JSON.parse(`{"title":"Document Repository","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/user/document-repository.md","filePath":"content/plugins/bcew-document-repository/user/document-repository.md"}`),p={name:`content/plugins/bcew-document-repository/user/document-repository.md`};function m(n,f,p,m,h,g){return e(),r(`div`,null,[...f[0]||=[t(`<h1 id="document-repository" tabindex="-1">Document Repository <a class="header-anchor" href="#document-repository" aria-label="Permalink to “Document Repository”">​</a></h1><p><img src="`+i+`" alt="Document Repository Overview" width="1127" height="819"></p><h2 id="prerequisites-and-access" tabindex="-1">Prerequisites and access <a class="header-anchor" href="#prerequisites-and-access" aria-label="Permalink to “Prerequisites and access”">​</a></h2><ul><li>Document Repository plugin installed and enabled.</li><li>WordPress Search plugin installed and enabled to search document metadata.</li><li>Admins and users with the configured Document Repository capability can upload, edit, and delete documents. The default capability is <code>upload_files</code>.</li></ul><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to “Where to find it”">​</a></h2><p>In WordPress Admin: <strong>Document Repository</strong> (left navigation).</p><p><img src="`+u+`" alt="Where To Find Document Repository" width="541" height="457"></p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What you can do”">​</a></h2><ul><li>Upload PDF documents.</li><li>Organize documents with titles and excerpts.</li><li>Add custom metadata fields defined in <strong>Metadata Settings</strong>.</li><li>Search and filter by document content and metadata.</li><li>Use standard list and spreadsheet views.</li></ul><h2 id="upload-a-document" tabindex="-1">Upload a document <a class="header-anchor" href="#upload-a-document" aria-label="Permalink to “Upload a document”">​</a></h2><ol><li>Go to <strong>Document Repository</strong> in WordPress Admin.</li><li>Drag files into the <strong>Drag &amp; Drop</strong> area, or click <strong>Choose Files</strong>.</li><li>Select PDF files and click <strong>Open</strong>.</li><li>Uploaded documents appear in the list.</li></ol><p>Only valid PDF files are accepted.</p><p><img src="`+o+`" alt="Upload a Document" width="640" height="436"></p><h2 id="edit-document-metadata" tabindex="-1">Edit document metadata <a class="header-anchor" href="#edit-document-metadata" aria-label="Permalink to “Edit document metadata”">​</a></h2><ol><li>Go to <strong>Document Repository</strong>.</li><li>Click the pencil icon to open the editor, or edit inline in <strong>Spreadsheet Mode</strong>.</li><li>Update the <strong>Title</strong>, <strong>Excerpt</strong>, and any <strong>Metadata Fields</strong>.</li><li>Click <strong>Save Changes</strong>.</li></ol><p>Taxonomy fields may contain one or more values, separated by commas or Enter.</p><p><img src="`+d+`" alt="Edit a Document" width="640" height="424"></p><h2 id="delete-trash-a-document" tabindex="-1">Delete (trash) a document <a class="header-anchor" href="#delete-trash-a-document" aria-label="Permalink to “Delete (trash) a document”">​</a></h2><ol><li>Select documents and click <strong>Trash Selected</strong>, or click the <strong>Trash</strong> icon beside a document.</li><li>Review the confirmation and confirm, or cancel.</li></ol><p>Trashed documents can be restored or permanently deleted from the <strong>Trash</strong> view. Permanent deletion removes the file and associated metadata.</p><p><img src="`+l+`" alt="Delete a Document" width="640" height="412"></p><h2 id="search-documents" tabindex="-1">Search documents <a class="header-anchor" href="#search-documents" aria-label="Permalink to “Search documents”">​</a></h2><p>Use the <strong>Search</strong> box, enter a keyword, then press <strong>Enter</strong> or click <strong>Search</strong>. Search matches titles, excerpts, and metadata. Clear the input and search again, or click <strong>X</strong>, to reset.</p><p><img src="`+a+`" alt="Search For Documents in the repository" width="640" height="424"></p><h2 id="view-modes" tabindex="-1">View modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to “View modes”">​</a></h2><p>Standard view shows titles, excerpts, configured metadata, file size and type, revisions, and actions. Spreadsheet view shows documents and metadata in columns and supports inline editing. Use the <strong>View Mode</strong> toggle in the top-right to switch.</p><p><img src="`+s+`" alt="Switch View Modes" width="640" height="398"></p><h2 id="document-revisions" tabindex="-1">Document revisions <a class="header-anchor" href="#document-revisions" aria-label="Permalink to “Document revisions”">​</a></h2><ol><li>Click <strong>Revisions</strong> for a document.</li><li>Use <strong>Previous</strong> and <strong>Next</strong> to navigate versions.</li><li>Click <strong>Restore this Revision</strong> to apply it; this opens the editor.</li><li>Optionally edit the revision text and save.</li></ol><p><img src="`+c+`" alt="Document Revisions" width="640" height="398"></p><p>Documents can be <strong>Published</strong>, <strong>Draft</strong>, or <strong>Pending Review</strong>. To restore a trashed document, open <strong>Trash</strong>, select it, and click <strong>Restore</strong>.</p><h2 id="tips-and-troubleshooting" tabindex="-1">Tips and troubleshooting <a class="header-anchor" href="#tips-and-troubleshooting" aria-label="Permalink to “Tips and troubleshooting”">​</a></h2><ul><li>Use descriptive titles and excerpts; define metadata fields before large uploads.</li><li>Confirm files are valid PDFs and within hosting size limits if upload fails.</li><li>If search misses documents, ensure the WordPress Search plugin is active and has indexed metadata.</li><li>If fields do not appear, create them in <strong>Metadata Settings</strong> and refresh.</li><li>Verify user permissions if editing or deleting is unavailable.</li></ul>`,33)]])}var h=n(p,[[`render`,m]]);export{f as __pageData,h as default};